workspace "Claims Center" "Insurance claims platform" {

    !identifiers hierarchical

    model {

        properties {
            "structurizr.inspection.softwareSystem.documentation" "ignore"
            "structurizr.inspection.softwareSystem.decisions" "ignore"
            "structurizr.inspection.element.disconnected" "ignore"
        }

        policyholder = person "Policyholder" "Reports claims and tracks their progress"
        adjuster = person "Adjuster" "Processes assigned claims in the adjuster workbench"

        claimsCenter = softwareSystem "Claims Center" "The insurance company's claims platform" {

            webPortal = container "Web Portal" "Where policyholders report claims and track their progress" "Web Application" "Web"
            mobileAppBackend = container "Mobile App Backend" "Serves the insurer's mobile app" "REST API"
            claimsIntake = container "Claims Intake Service" "Registers new claims" "Service"
            triage = container "Triage Service" "Classifies and prioritizes claims" "Service"
            assessment = container "Assessment Service" "Calculates settlement amounts" "Service"
            payout = container "Payout Service" "Executes claim settlements" "Service"
            fraudScreening = container "Fraud Screening Service" "Flags suspicious claims" "Service"
            documentService = container "Document Service" "Accepts claim photos and reports" "Service"
            notification = container "Notification Service" "Emails and messages policyholders" "Service"
            assignment = container "Assignment Service" "Routes claims to adjusters" "Service"
            adjusterWorkbench = container "Adjuster Workbench" "Where staff process their assigned claims" "Web Application" "Web"
            policyVerification = container "Policy Verification Service" "Checks that a claim is covered by the policy" "Service"
            reinsuranceAllocation = container "Reinsurance Allocation Service" "Apportions large losses across reinsurance partners" "Service"
            batchScheduler = container "Batch Scheduler" "Runs the nightly reserves calculation" "Batch Job"
            eventQueue = container "Event Queue" "Carries claim events between the application parts" "Message Queue" "Queue"
            claimsDb = container "Claims Database" "Stores claim records" "Relational Database" "Database"
            policyDb = container "Policy Database" "Stores policy and cover records" "Relational Database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Relational Database" "Database"
            documentStore = container "Document Store" "Holds claim photos, reports, and correspondence" "Object Storage" "Storage"
        }

        nationalBureau = softwareSystem "National Claims Data Bureau" "External claims data bureau operated by a different organization" "External"
        clearingHouse = softwareSystem "Clearing House" "External clearing house operated by a different organization" "External"

        # People to containers
        policyholder -> claimsCenter.webPortal "reports claims and tracks their progress" "HTTPS"
        policyholder -> claimsCenter.mobileAppBackend "reports claims and tracks their progress via the insurer's mobile app" "HTTPS"
        adjuster -> claimsCenter.adjusterWorkbench "processes assigned claims" "HTTPS"

        # Containers to external systems
        claimsCenter.fraudScreening -> nationalBureau "consults claims data with" "HTTPS"
        claimsCenter.payout -> clearingHouse "executes settlements through" "HTTPS"

        # Web portal and mobile app backend to services
        claimsCenter.webPortal -> claimsCenter.claimsIntake "submits new claims to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.documentService "uploads claim photos and reports to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.notification "requests status notifications from" "HTTPS"

        claimsCenter.mobileAppBackend -> claimsCenter.claimsIntake "submits new claims to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.documentService "uploads claim photos and reports to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.notification "requests status notifications from" "HTTPS"

        # Claim flow
        claimsCenter.claimsIntake -> claimsCenter.triage "hands accepted claims to" "HTTPS"
        claimsCenter.triage -> claimsCenter.assessment "routes claims to" "HTTPS"
        claimsCenter.assessment -> claimsCenter.payout "requests settlements from" "HTTPS"

        # Screening, verification, and assignment
        claimsCenter.claimsIntake -> claimsCenter.fraudScreening "sends each incoming claim to for screening" "HTTPS"
        claimsCenter.claimsIntake -> claimsCenter.policyVerification "sends each incoming claim to for cover checks" "HTTPS"
        claimsCenter.policyVerification -> claimsCenter.policyDb "checks cover against policy records" "SQL"
        claimsCenter.assignment -> claimsCenter.adjusterWorkbench "routes claims to" "HTTPS"

        # Data, batch, and notification
        claimsCenter.documentService -> claimsCenter.documentStore "reads claim photos and reports from" "HTTPS"
        claimsCenter.batchScheduler -> claimsCenter.claimsDb "reads and writes claim records" "SQL"
        claimsCenter.batchScheduler -> claimsCenter.policyDb "reads and writes policy records" "SQL"
        claimsCenter.notification -> policyholder "emails and messages claim status changes to" "Email/SMS"
    }

    views {

        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }

        container claimsCenter "Containers" {
            include *
            autoLayout
            title "Containers for Claims Center"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Storage" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
        }
    }

    configuration {
        scope softwareSystem
    }
}

